/** Conservative proof for reusing a recorded pickup as a planned guide's origin.
 * BOL, PO and load/order identifiers remain separate. Blank is not confirmation.
 */
const norm=v=>String(v??'').trim().replace(/\s+/g,' ').toUpperCase();
const values=list=>[...new Set(list.map(norm).filter(Boolean))];
const real=e=>e && e.status==='ON' && !['voided','deleted','synthetic','syntheticCoverage','displayOnly','carriedFromPreviousDay','continuityGenerated'].some(k=>e[k]);
export function pickupGuideIdentity(event,guide) {
  const failures=[];
  if(!real(event)||!guide?.id)return {matches:false,failures:['missing_recorded_pickup']};
  const activity=[event.note,...(Array.isArray(event.reasons)?event.reasons:[])].join(' ');
  if(!/\b(?:pickup|pick up|loading)\b/i.test(activity))failures.push('not_pickup');
  const descriptions=[...String(event.description||'').matchAll(/\bLoad\s+([A-Z0-9][A-Z0-9_-]*)/gi)].map(m=>m[1]);
  const eventIds=values([event.loadNo,event.shippingDocs,event.pickedUpLoadNo,...descriptions]);
  const guideIds=values([guide.loadNo,guide.orderNo]);
  if(!eventIds.length||!guideIds.length)failures.push('missing_load_identity');
  else if(!eventIds.every(id=>guideIds.includes(id)))failures.push('load_identity_conflict');
  // A BOL can join only through a separately labelled BOL; never compare it to a load id.
  const guideBols=values([guide.bol,guide.bolNo,guide.bolNumber]);
  if(event.bol && guideBols.length && !guideBols.includes(norm(event.bol)))failures.push('bol_conflict');
  const destinations=[];
  if(norm(event.destination)){
    const raw=String(event.destination).trim();
    destinations.push(norm(/,\s*[A-Za-z]{2}$/.test(raw)?raw:[raw,event.destinationState].filter(Boolean).join(', ')));
  }
  for(const m of String(event.description||'').matchAll(/\bTo\s+([^·|\n]+?,\s*[A-Z]{2})(?=\s*(?:[·|\n]|$))/gi))destinations.push(norm(m[1]));
  const stops=(guide.stops||[]).filter(s=>s?.type==='delivery').map(s=>norm([s.city,s.state].filter(Boolean).join(', ')));
  if(stops.length && !destinations.length)failures.push('missing_destination');
  if(destinations.length && (!stops.length||destinations.some(d=>!stops.includes(d))))failures.push('destination_conflict');
  return {matches:failures.length===0,failures,eventIds,guideIds};
}

