/** Pure, explicit-edit synchronization. Never called by startup, import or OCR. */
export function syncEditedPickupReferences(before, after, command) {
 const {day,id,patch={}}=command;
 if(!['shippingDocs','loadNo','destination','destinationState'].some(key=>Object.hasOwn(patch,key)))return after;
 const old=before.eventsByDay?.[day]?.find(e=>e?.id===id);
 let event=after.eventsByDay?.[day]?.find(e=>e?.id===id);
 if(!old||!event||event.status!=='ON'||['voided','deleted','syntheticCoverage','displayOnly','synthetic','continuityGenerated'].some(k=>old[k]||event[k]))return after;
 if(!/\b(?:pickup|loading)\b/i.test([event.note,...(Array.isArray(event.reasons)?event.reasons:[])].join(' ')))return after;
 // These are derived aliases of the same load reference. Only aliases exactly
 // equal to the old reference follow an explicit load-number edit. Distinct BOL,
 // PO, other load references and source description remain independent.
 if(Object.hasOwn(patch,'loadNo') && event.loadNo!==old.loadNo){
  const oldRefs=new Set([old.loadNo,old.shippingDocs].filter(v=>typeof v==='string'&&v));
  const value=event.loadNo||'',fields={};
  if(oldRefs.has(event.pickedUpLoadNo))fields.pickedUpLoadNo=value;
  if(Array.isArray(event.transitionLoadNos))fields.transitionLoadNos=event.transitionLoadNos.map(v=>oldRefs.has(v)?value:v);
  for(const [key,prefix] of [['transitionSummary','Picked up '],['displayShippingDocs','Load ']]){
   if([...oldRefs].some(v=>event[key]===prefix+v))fields[key]=value?prefix+value:'';
  }
  event={...event,...fields};
  after={...after,eventsByDay:{...after.eventsByDay,[day]:after.eventsByDay[day].map(e=>e.id===id?event:e)}};
 }
 const routes=after.routeLegsByDay?.[day]||[];
 let changed=false;
 const next=routes.map(leg=>{
  if(leg?.pickupEventId!==id||!['pickup_event','manual_form'].includes(leg.source)||/^(cancelled|superseded)$/.test(leg.status))return leg;
  const updates={};
  if(Object.hasOwn(patch,'shippingDocs'))updates.shippingDocs=event.shippingDocs;
  if(Object.hasOwn(patch,'loadNo')){
   updates.loadNo=event.loadNo;
   const oldRefs=new Set([old.loadNo,old.shippingDocs].filter(Boolean));
   if(oldRefs.has(leg.pickedUpLoadNo))updates.pickedUpLoadNo=event.loadNo;
   if(Array.isArray(leg.transitionLoadNos))updates.transitionLoadNos=leg.transitionLoadNos.map(v=>oldRefs.has(v)?event.loadNo:v);
  }
  if(Object.hasOwn(patch,'destination')||Object.hasOwn(patch,'destinationState')){
   const parts=String(event.destination||'').split(',').map(v=>v.trim());
   updates.toState=String(event.destinationState|| (parts.length>1?parts.at(-1):'')).toUpperCase();
   updates.toCity=parts.length>1?parts.slice(0,-1).join(', '):parts[0];
  }
  if(Object.entries(updates).every(([key,value])=>JSON.stringify(value)===JSON.stringify(leg[key])))return leg;
  changed=true;return {...leg,...updates};
 });
 return changed?{...after,routeLegsByDay:{...after.routeLegsByDay,[day]:next}}:after;
}
